import math

R = 8.314e-3

def optimal_binding(T, p, alpha=0.5, K0=1e-6):
    # d ln k / dE = alpha/RT and d ln theta / dE = -(1/RT) / (1 + Kp); they cancel when Kp = 1/alpha - 1
    return -R * T * math.log((1 / alpha - 1) / (K0 * p))
